            if all(grid[i][j] == 8 for i, j in cells) and not (cells & used):
                for i, j in cells:
                    out[i][j] = 1
                used |= cells

    # Color remaining connected groups distinctly.
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 8 and (r, c) not in used}
    color = 2
    while remaining:
        start = min(remaining)
        remaining.remove(start)
        stack = [start]
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for p in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                if p in remaining:
                    remaining.remove(p)
                    stack.append(p)
        for r, c in comp:
            out[r][c] = color
        color = color + 1 if color < 4 else 2
    return out
