def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    result = [[0] * w for _ in range(h)]

    # Tile the shape with 2x2 squares and 3-cell L pieces.
    placements = []
    for r in range(h):
        for c in range(w):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if all(x < h and y < w for x, y in square):
                placements.append((square, 1))
            for miss, color in (((0, 0), 2), ((0, 1), 4),
                                ((1, 0), 3), ((1, 1), 2)):
                piece = {(r + dr, c + dc) for dr in (0, 1) for dc in (0, 1)
                         if (dr, dc) != miss}
                if all(x < h and y < w for x, y in piece):
                    placements.append((piece, color))

    by_cell = {p: [] for p in occupied}
    for cells, color in placements:
        if cells <= occupied:
            for p in cells:
                by_cell[p].append((cells, color))

    def solve(left):
        if not left:
            return []
        p = min(left, key=lambda q: sum(cells <= left for cells, _ in by_cell[q]))
        options = sorted(by_cell[p], key=lambda x: -len(x[0]))
        for cells, color in options:
            if cells <= left:
                rest = solve(left - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    tiling = solve(occupied)
    if tiling:
        for cells, color in tiling:
            for r, c in cells:
                result[r][c] = color
    return result
